import math

def pdf(x, m, s):
    return math.exp(-((x - m) ** 2) / (2 * s * s)) / (math.sqrt(2 * math.pi) * s)
x = 6.5
print(round(pdf(x, 5.0, 0.7), 4), round(pdf(x, 7.4, 1.0), 4))
# prints: 0.0574 0.2661

mix = [(0.30, 2, 0.8), (0.45, 5, 1.0), (0.25, 8, 0.9)]      # (weight, mean, sigma)
mixture = lambda x: sum(w * pdf(x, m, s) for w, m, s in mix)
for name, (w, m, s) in zip('ABC', mix):
    print(name, {'weight': w, 'mean': m, 'sigma': s})
# prints: A {'weight': 0.3, 'mean': 2, 'sigma': 0.8}
# prints: B {'weight': 0.45, 'mean': 5, 'sigma': 1.0}
# prints: C {'weight': 0.25, 'mean': 8, 'sigma': 0.9}
